entries[356461] = { ["name"] = "Doppelklingensichel", ["text"] = "200 Meter Reichweite\nSofort\nDer Leidensschmied schleudert seine Sichel auf sein aktuelles Ziel, fügt ihm 191696 körperlichen Schaden zu und belegt es mit ' Geschwärzte Rüstung '. Flammen brechen vom Einschlagsort aus und fügen allen anderen Spielercharakteren 143772 Feuerschaden zu. Weiter vom Ziel entfernte Spielercharaktere erleiden weniger Schaden.\n\nVon der Position des Ziels brechen Stachelwellen in 4 Richtungen hervor und bewegen sich nach außen." }
