entries[357550] = { ["name"] = "Lebende Bombe", ["text"] = "Wirken in 1.5 sek.\nDer Zaubernde macht Spielercharaktere zu lebenden Bomben, was ihnen alle 2 Sek. 15975 Feuerschaden zufügt und sie nach 8 Sek. explodieren lässt.\n\nDie Explosion fügt Spielercharakteren innerhalb von 8 Metern 31949 Feuerschaden zu." }
