entries[357564] = { ["name"] = "Seelenaffinität", ["text"] = "Unbegrenzte Reichweite\nSofort\nIhr und die Euch verwandte Seele erhaltet jeweils einen Bonus auf einen Sekundärwert, der von ihrem Pakt abhängt. Für Eure verwandte Seele wird dieser Bonus halbiert, jedoch werden beide Boni verdoppelt, während Eure Verbindung ermächtigt ist.\n\nKyrianer : Meisterschaft um 571 erhöht.\nNachtfae : Tempo um 6% erhöht.\nVenthyr : Kritische Trefferchance um 6% erhöht.\nNekrolords : Vielseitigkeit um 6% erhöht.\n(15s Abklingzeit)" }
entries[357565] = { ["name"] = "Flammende Stulpen", ["text"] = "100 Meter Reichweite\nSofort\nNahkampfangriffe verursachen Feuerschaden und 9 Sek. lang alle 3 Sek. zusätzlich 3994 Feuerschaden. Dieser Effekt ist stapelbar." }
