entries[357573] = { ["name"] = "Stygisches Lauffeuer", ["text"] = "Wirken in 3 sek.\nSeelenfunke erschafft Flammen in der Nähe, die anwachsen und nach 10 Sek. explodieren, was allen Spielercharakteren bis zu 100 Feuerschaden zufügt.\n\nDer Aufenthalt im Effektbereich einer Flamme verursacht alle 1 Sek. 22 Feuerschaden, verringert aber den Schaden der abschließenden Explosion." }
